// xz_decode_file driver for the trailing-bytes fixture test: exit 0 on
// decode success, 1 on refusal. The .xz fixtures (including one whose
// member ends exactly at the 4096-byte input-buffer boundary) are
// generated by test_xz_tail.py with Python's lzma module.
#include <stdio.h>

int xz_decode_file(const char *in_path, const char *out_path);

int main(int argc, char **argv)
{
    if (argc != 3) {
        fprintf(stderr, "usage: %s IN OUT\n", argv[0]);
        return 2;
    }
    return xz_decode_file(argv[1], argv[2]) == 0 ? 0 : 1;
}
